D={
80275:("Sentimentos: afraid","**Afraid / scared** = com medo. **Be afraid of** + coisa: *I'm afraid of ghosts.* Gritar: **scream**. Esconder: **hide**.",[("I'm {{afraid of}} ghosts.","Tenho medo de fantasmas."),("She {{screams}}.","Ela grita."),("We {{hide}} behind the sofa.","Nos escondemos atrás do sofá."),("It's a scary show.","É um show assustador.")],"“Tenho medo de monstros”:",["I'm afraid of monsters.","I afraid monsters.","I have afraid monsters."],0,"afraid of."),
80276:("Livros","Tipos: **paperback** (capa mole), **hardcover** (capa dura). Partes: **chapter, page, cover, author.** *Who is the author?*",[("A {{paperback}} is cheap.","Um livro de bolso é barato."),("A {{hardcover}} is strong.","Um livro de capa dura é resistente."),("Read {{chapter}} two.","Leia o capítulo dois."),("Who is the {{author}}?","Quem é o autor?")],"“Capa dura”:",["hardcover","paperback","cover soft"],0,"Hardcover."),
910034:("Ask, answer","**Ask a question, give an answer, get a response.** Não se diz *make an answer*. **Answer key** = gabarito.",[("{{Ask}} a question.","Faça uma pergunta."),("{{Give}} an answer.","Dê uma resposta."),("Check the {{answer key}}.","Confira o gabarito."),("That's {{incorrect}}.","Isso está incorreto.")],"“Fazer uma pergunta”:",["ask a question","do a question","make a question"],0,"ask a question."),
80277:("Jogo de cartas","Cartas: **shuffle** (embaralhar), **deal** (distribuir), **play a card**. *Shuffle the deck. Deal the cards.*",[("{{Shuffle}} the deck.","Embaralhe o baralho."),("{{Deal}} the cards.","Distribua as cartas."),("{{Play}} a queen.","Jogue uma dama."),("The winner takes all.","O vencedor leva tudo.")],"“Embaralhar”:",["shuffle","deal","play"],0,"Shuffle."),
80278:("Quebra-cabeça","Quebra-cabeça: **find the edge pieces, fit the pieces together.** **Missing** = faltando. *One piece is missing.*",[("{{Find}} the edge pieces.","Encontre as peças das bordas."),("{{Fit}} them together.","Encaixe-as."),("One piece is {{missing}}.","Falta uma peça."),("Look at the picture.","Olhe a imagem.")],"“Faltando”:",["missing","middle","edge"],0,"Missing."),
80279:("Go + -ing","Esportes de ação: **go + -ing**: *go skiing, go swimming, go running.* *We go skiing in winter.*",[("We {{go skiing}} in winter.","Vamos esquiar no inverno."),("She {{goes swimming}}.","Ela vai nadar."),("They {{go running}}.","Eles vão correr."),("Wear a helmet.","Use capacete.")],"“Ir correr”:",["go running","go to run","go runs"],0,"go + -ing."),
80280:("Competição","Corrida: **pedal, race, finish, win a prize.** *Ready, set, go!* **Finish line** = linha de chegada.",[("{{Pedal}} fast!","Pedale rápido!"),("{{Race}} to the finish.","Corra até a chegada."),("{{Win}} a prize.","Ganhe um prêmio."),("{{Ready, set, go}}!","Preparar, apontar, já!")],"“Linha de chegada”:",["finish line","start line","speed lane"],0,"Finish line."),
80281:("Ao ar livre","Soltar pipa: **fly a kite.** *The wind is strong. The kite goes up.* Verbo **fly** para pipas e pássaros.",[("{{Fly}} a kite.","Solte pipa."),("The {{breeze}} is soft.","A brisa é suave."),("The kite goes {{up}}.","A pipa sobe."),("Hold the string.","Segure a linha.")],"“Soltar pipa”:",["fly a kite","play a kite","do a kite"],0,"fly."),
80282:("Primeiro dia","Primeiro dia: **Meet your homeroom teacher. This is your desk.** **Meet** = conhecer. *Nice to meet you!*",[("{{Meet}} your teacher.","Conheça seu professor."),("{{This is}} your desk.","Esta é sua carteira."),("{{Nice to meet you}}!","Prazer em conhecer você!"),("The bell rings.","O sinal toca.")],"“Prazer em conhecer”:",["Nice to meet you.","Good to know.","Happy see you."],0,"Nice to meet you."),
80283:("Pedir material","Pedir: **May I borrow a marker? Can I use your ruler?** Agradeça: **Thanks!** Devolva: **Here you go.**",[("{{May I borrow}} a marker?","Posso pegar um marcador emprestado?"),("{{Can I use}} your ruler?","Posso usar sua régua?"),("{{Here you go}}.","Aqui está."),("{{Thanks}}!","Obrigado!")],"“Aqui está”:",["Here you go.","Take there.","Is here."],0,"Here you go."),
80284:("Hard or easy","**Hard** = difícil, **easy** = fácil, **boring** = chato. *Math is hard. History is easy.* Adjetivo depois do be.",[("Math {{is hard}}.","Matemática é difícil."),("History {{is easy}}.","História é fácil."),("Science {{is boring}} for me.","Ciências é chato para mim."),("I like art.","Gosto de arte.")],"“Matéria difícil”:",["hard subject","easy subject","boring subject"],0,"Hard."),
910035:("Work hard","**Hard** e **well**: *work hard* (muito), *do well* (bem). **Hardly** = quase não. *Study hard!*",[("{{Work hard}}.","Trabalhe duro."),("{{Study hard}}.","Estude muito."),("You {{did well}}.","Você foi bem."),("He drives {{fast}}.","Ele dirige rápido.")],"“Estude muito”:",["Study hard.","Study hardly.","Study well hard."],0,"hard = muito."),
80285:("Hora de estudar","Estudos: **study, review, do homework, take an exam.** *I study at the library.* Para exame: **take an exam**.",[("I {{study}} at the library.","Estudo na biblioteca."),("I {{do homework}}.","Faço lição de casa."),("We {{take an exam}} on Friday.","Fazemos prova na sexta."),("Open your notebook.","Abra seu caderno.")],"“Fazer uma prova”:",["take an exam","do an exam","make exam"],0,"take an exam."),
80286:("Primeira reunião","No trabalho: **The meeting starts at nine. The boss talks to the team.** Presente simples: he/she/it com **-s**.",[("The meeting {{starts}} at nine.","A reunião começa às nove."),("The boss {{talks}} to the team.","O chefe fala com a equipe."),("We {{drink}} coffee.","Tomamos café."),("Take a seat.","Sente-se.")],"Complete: “The boss ___ a plan.”",["make","makes","making"],1,"3ª pessoa: -s."),
80287:("Entrevista","Entrevista: **Can you start today? Yes, I can.** **Can** = capacidade/permissão. *I can work on Monday.*",[("{{Can you}} start today?","Você pode começar hoje?"),("Yes, {{I can}}.","Sim, posso."),("I {{can}} work on Monday.","Posso trabalhar na segunda."),("Here's my resume.","Aqui está meu currículo.")],"“Você pode começar?”",["Can you start?","You can start?","Start can you?"],0,"Can you…?"),
80288:("Should","**Should** = deveria. *Should I print it? Yes, you should.* **Should** + verbo base.",[("{{Should I}} print it?","Devo imprimir?"),("Yes, {{you should}}.","Sim, deve."),("You {{should}} save the file.","Você deveria salvar o arquivo."),("Press the button.","Aperte o botão.")],"“Eu devo ligar?”",["Should I call?","I should call?","Do I should call?"],0,"Should I…?"),
80289:("Ao telefone","Telefone no escritório: **Which extension? One moment, please.** **Hold on.** **Leave a message.**",[("{{Which extension}}?","Qual ramal?"),("{{One moment}}, please.","Um momento, por favor."),("{{Hold on}}.","Aguarde."),("Leave a message.","Deixe um recado.")],"“Um momento”:",["One moment.","Moment one.","A time."],0,"One moment."),
80290:("Dias da semana","Semana: **on Monday, on Tuesday…** *I'm busy on Monday. I'm free on Friday.* **Free** = livre.",[("I'm {{busy}} on Monday.","Estou ocupado na segunda."),("I'm {{free}} on Friday.","Estou livre na sexta."),("It's on my calendar.","Está no meu calendário."),("Let's plan.","Vamos planejar.")],"“Livre”:",["free","busy","plan"],0,"Free."),
80291:("Material de escritório","Objetos: **stapler, folder, tape, scissors.** Pedir: **Can I use the stapler?** *Where is the tape?* Singular **is**.",[("{{Where is}} the stapler?","Onde está o grampeador?"),("{{Where are}} the scissors?","Onde está a tesoura?"),("It's in the drawer.","Está na gaveta."),("Take the tape.","Pegue a fita.")],"Complete: “Where ___ the scissors?”",["is","are","do"],1,"Scissors = plural."),
80292:("Sala de descanso","Lugares: **There is a microwave in the breakroom.** **There is** (singular) e **there are** (plural). *Use a napkin.*",[("{{There is}} a microwave.","Há um micro-ondas."),("{{There are}} sandwiches.","Há sanduíches."),("{{There is}} a fridge.","Há uma geladeira."),("Use a napkin.","Use um guardanapo.")],"Complete: “___ two chairs.”",["There is","There are","There be"],1,"Plural."),
910036:("Fall asleep, stay up","**Fall asleep** = adormecer. **Stay up** = ficar acordado. **Go to bed** = ir dormir. *I stay up late.*",[("I {{fall asleep}} fast.","Adormeço rápido."),("We {{stay up}} late.","Ficamos acordados até tarde."),("They {{go to bed}} at ten.","Eles vão dormir às dez."),("I snore at night.","Ronco à noite.")],"“Ficar acordado”:",["stay up","fall up","go up"],0,"Stay up."),
80293:("Must","**Must** = deve (obrigação). *You must wear gloves.* Negativo: **mustn't** = proibido. *You mustn't run.*",[("You {{must}} wear gloves.","Você deve usar luvas."),("You {{must}} wear goggles.","Você deve usar óculos."),("You {{mustn't}} run.","Você não deve correr."),("It's for safety.","É por segurança.")],"“É proibido correr”:",["You mustn't run.","You must run no.","You don't must run."],0,"mustn't."),
80294:("O que estão fazendo?","Presente contínuo: **be + -ing**. *They are playing. The pirate is looking at the map.* Para ações agora.",[("They {{are playing}}.","Eles estão brincando."),("The pirate {{is looking}} at the map.","O pirata está olhando o mapa."),("The fairy {{is flying}}.","A fada está voando."),("What are they doing?","O que eles estão fazendo?")],"Complete: “She ___ now.” (sing)",["sings","is singing","sing"],1,"be + -ing."),
80295:("Right now","**Right now** reforça o presente contínuo. *The squirrel is eating a nut right now.* Verbo + **-ing**.",[("The squirrel {{is eating}} a nut {{right now}}.","O esquilo está comendo uma noz agora."),("The owl {{is sleeping}}.","A coruja está dormindo."),("The cat {{is climbing}}.","O gato está subindo."),("Look at the tree!","Olhe a árvore!")],"“Agora mesmo”:",["right now","right then","now right"],0,"Right now."),
80296:("Negativa contínua","Negativa: **be + not + -ing.** *I'm not playing. He isn't coming.* **Not now!** = agora não!",[("I {{'m not}} playing.","Não estou brincando."),("He {{isn't}} coming.","Ele não está vindo."),("{{Not now}}, Mom!","Agora não, mãe!"),("The rabbit isn't eating.","O coelho não está comendo.")],"“Não estou comendo”:",["I'm not eating.","I don't eating.","I not am eating."],0,"be + not + -ing."),
80297:("Where are you?","Onde: **Where are you going? Where is he sleeping?** **Where + be + sujeito + -ing**.",[("{{Where are}} you going?","Para onde você vai?"),("{{Where is}} the whale swimming?","Onde a baleia está nadando?"),("I'm in the boat.","Estou no barco."),("The fish is under the lamp.","O peixe está embaixo da luminária.")],"“Onde você está?”",["Where are you?","Where you are?","Where is you?"],0,"Where are you?"),
80298:("Perguntas no contínuo","Pergunta: **Are they cheering? — Yes, they are.** **be + sujeito + -ing**. Resposta curta com **be**.",[("{{Are they}} cheering?","Eles estão torcendo?"),("Yes, {{they are}}.","Sim."),("{{Is he}} hitting?","Ele está rebatendo?"),("No, {{he isn't}}.","Não.")],"Resposta curta de Is she running? (não):",["No, she isn't.","No, she don't.","No, she not."],0,"isn't."),
80299:("It is raining","Tempo agora: **It is raining. It is snowing.** Use **it is + -ing**. Pergunta: **Is it raining?** *Listen!*",[("{{It is raining}}.","Está chovendo."),("{{It is thundering}}.","Está trovejando."),("I take an umbrella.","Levo um guarda-chuva."),("Look at the puddle!","Olhe a poça!")],"“Está nevando”:",["It is snowing.","It snows being.","Snowing it is."],0,"It is + -ing."),
80300:("Passado: -ed","Passado regular: **verbo + -ed**: *watch → watched, cook → cooked.* *We watched a movie on Sunday.*",[("We {{watched}} a movie.","Assistimos a um filme."),("I {{cooked}} dinner.","Fiz o jantar."),("She {{baked}} a cake.","Ela fez um bolo."),("We napped after lunch.","Cochilamos depois do almoço.")],"Passado de watch:",["watchd","watched","watching"],1,"watch + ed."),
910037:("Check in, check out","**Check in** = fazer check-in. **Check out** = fazer check-out. *Check in at three. Check out at noon.*",[("{{Check in}} at three.","Faça check-in às três."),("{{Check out}} at noon.","Faça check-out ao meio-dia."),("I need a single room.","Preciso de um quarto de solteiro."),("The receptionist helps you.","A recepcionista ajuda você.")],"“Fazer check-out”:",["check out","check off","take out"],0,"Check out."),
80301:("-ed e a ortografia","Se termina em **-e**, só **-d**: *dance → danced.* **Consoante+y** → **-ied**: *cry → cried.* Consoante única: dobra: *plan → planned.*",[("We {{danced}}.","Dançamos."),("He {{cried}}.","Ele chorou."),("They {{planned}} a party.","Eles planejaram uma festa."),("She {{smiled}}.","Ela sorriu.")],"Passado de plan:",["planed","planned","plan-ed"],1,"Dobra a consoante."),
80302:("Pronúncia de -ed","**-ed** soa de 3 jeitos: **/t/** (*jumped*), **/d/** (*turned*), **/id/** (*lifted*). *Lifted* tem uma sílaba a mais.",[("He {{jumped}}.","Ele pulou. (soa /t/)"),("She {{turned}}.","Ela virou. (soa /d/)"),("They {{lifted}} the harp.","Eles levantaram a harpa. (soa /id/)"),("The giant fell.","O gigante caiu.")],"Qual termina em /id/?",["lifted","jumped","turned"],0,"Lifted: sílaba extra."),
80303:("Did + verbo base","Pergunta no passado: **Did you write it?** O verbo volta ao **infinitivo**. *Did she go? No, she didn't.*",[("{{Did you write}} the letter?","Você escreveu a carta?"),("Yes, {{I did}}.","Sim."),("{{Did she eat}} the porridge?","Ela comeu o mingau?"),("No, {{she didn't}}.","Não.")],"Qual está certa?",["Did you wrote?","Did you write?","You did write?"],1,"did + verbo base."),
80304:("Didn't + verbo base","Negativa no passado: **didn't + verbo base.** *I didn't sleep. He didn't hear the noise.* Sem **-ed**.",[("I {{didn't sleep}}.","Não dormi."),("He {{didn't hear}} the noise.","Ele não ouviu o barulho."),("We {{didn't close}} the window.","Não fechamos a janela."),("It was a long night.","Foi uma noite longa.")],"Qual está certa?",["I didn't slept.","I didn't sleep.","I not slept."],1,"didn't + base."),
}
